# SPDX-FileContributor: Ion Reguera <ion@stagelab.coop>
#
# Regenerates test/fixtures/mediadecoder_fixtures.h: short 440 Hz sines at -30 dBFS encoded with every codec
# whose FFmpeg decoder reports a known channel layout (the class that crashed on mediadecoder f83ce02,
# see test_mediadecoder_layout.cpp), plus a PCM WAV control (UNSPEC layout), embedded as C arrays so the
# test needs no external files (python3 does the embedding; casas has no xxd). Run from this directory on casas
# (ffmpeg with libmp3lame, libvorbis, libopus).
set -euo pipefail
cd "$(dirname "$0")"
T=$(mktemp -d); trap 'rm -rf "$T"' EXIT
F="ffmpeg -hide_banner -loglevel error -y -bitexact"
src() { echo "sine=f=440:d=$1:sample_rate=$2,volume=-27dB"; }   # lavfi sine is -3 dBFS: -27 dB -> -30 dBFS
$F -f lavfi -i "$(src 0.3 44100)" -ac 1 -c:a libmp3lame -b:a 32k -write_xing 0 -id3v2_version 0 "$T/fx_mp3.mp3"
$F -f lavfi -i "$(src 0.3 22050)" -ac 1 -c:a libvorbis -q:a 0 "$T/fx_vorbis.ogg"
$F -f lavfi -i "$(src 0.3 48000)" -ac 1 -c:a libopus -b:a 24k "$T/fx_opus.opus"
$F -f lavfi -i "$(src 0.3 48000)" -ac 1 -c:a libopus -b:a 24k -f webm "$T/fx_webm_opus.weba"
$F -f lavfi -i "$(src 0.25 8000)" -ac 1 -c:a flac "$T/fx_flac.flac"
$F -f lavfi -i "$(src 0.3 22050)" -ac 1 -c:a aac -b:a 24k "$T/fx_aac.m4a"
$F -f lavfi -i "$(src 0.25 8000)" -ac 1 -c:a pcm_s16le "$T/fx_pcm.wav"
OUT=mediadecoder_fixtures.h
{
  echo "// SPDX-FileCopyrightText: 2026 Stagelab Coop SCCL"
  echo "// SPDX-License-Identifier: GPL-3.0-or-later"
  echo "// SPDX-FileContributor: Ion Reguera <ion@stagelab.coop>"
  echo "// Generated by test/fixtures/gen.sh -- do not edit."
  echo "#pragma once"
  for f in fx_mp3.mp3 fx_vorbis.ogg fx_opus.opus fx_webm_opus.weba fx_flac.flac fx_aac.m4a fx_pcm.wav; do
    sz=$(stat -c %s "$T/$f"); [ "$sz" -le 20480 ] || { echo "$f is $sz bytes (> 20 KB)" >&2; exit 1; }
    python3 -c 'import sys,re
p=sys.argv[1]; n=re.sub(r"[^A-Za-z0-9]","_",p.rsplit("/",1)[1]); d=open(p,"rb").read()
print("static const unsigned char %s[] = {" % n)
for i in range(0,len(d),12): print("  "+", ".join("0x%02x" % b for b in d[i:i+12])+",")
print("};"); print("static const unsigned int %s_len = %d;" % (n,len(d)))' "$T/$f"
  done
} > "$OUT"
ls -la "$OUT"; for f in "$T"/*; do echo "$(basename "$f") $(stat -c %s "$f")"; done
